package com.drivique.api.controller;import com.drivique.api.dto.*;import com.drivique.api.service.IncidentService;import jakarta.validation.Valid;import java.util.UUID;import org.springframework.http.HttpStatus;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;
@RestController @RequestMapping("/v1/incidents") public class IncidentController{private final IncidentService service;public IncidentController(IncidentService service){this.service=service;}@PostMapping @ResponseStatus(HttpStatus.CREATED) public UUID create(@Valid @RequestBody IncidentRequestDTO input,Authentication a){return service.create(input,a.getName());}@PostMapping(value="/{id}/responses",consumes="multipart/form-data") @ResponseStatus(HttpStatus.CREATED) public void respond(@PathVariable UUID id,@RequestPart("message") String message,@RequestPart(value="attachment",required=false) MultipartFile attachment,Authentication a){service.respond(id,message,attachment,a.getName());}@PatchMapping("/{id}/status") @PreAuthorize("hasAnyRole('EMPLOYEE','BRANCH_ADMIN','ADMIN','SUPER_ADMIN','AGENT')") public void status(@PathVariable UUID id,@Valid @RequestBody IncidentStatusRequestDTO input){service.status(id,input);}}
